"""Offline themed arcade victory stamps, generated by MobiIoT."""
from PIL import Image
import json

def build_gym_stamp(root):
    recipe=json.loads((root/'assets/gyms/defeated-themed-slices.json').read_text())
    atlas=Image.open(root/recipe['source']).convert('RGBA')
    for spec in recipe['slices']:
        im=atlas.crop(tuple(spec['box']))
        im.putalpha(im.getchannel('A').point(lambda a:255 if a>=recipe['alphaThreshold'] else 0))
        im=im.crop(im.getbbox());im.thumbnail((68,24),Image.Resampling.NEAREST)
        im=im.quantize(colors=32,method=Image.Quantize.FASTOCTREE).convert('RGBA')
        im.putalpha(im.getchannel('A').point(lambda a:255 if a>=128 else 0))
        out=Image.new('RGBA',(68,24));out.alpha_composite(im,((68-im.width)//2,(24-im.height)//2))
        out.resize((136,48),Image.Resampling.NEAREST).save(root/f'assets/gyms/{spec["name"]}.png')

if __name__=='__main__':
    from pathlib import Path
    build_gym_stamp(Path(__file__).resolve().parents[1])
